sys_script_include.script:
var AICopilotFeedback = Class.create()
AICopilotFeedback.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    saveFeedback: function() {
        var incidentNumber = this.getParameter('sysparm_incident_number') || '';
        var articleId = this.getParameter('sysparm_article_id') || '';
        var articleTitle = this.getParameter('sysparm_article_title') || '';
        var rating = this.getParameter('sysparm_rating') || '';
        var comment = this.getParameter('sysparm_comment') || '';
        var score = this.getParameter('sysparm_score') || '';

        try {
            var gr = new GlideRecord('x_2220006_ai_cop_0_fb');
            gr.initialize();
            gr.setValue('incident_number', incidentNumber);
            gr.setValue('article_id', articleId);
            gr.setValue('article_title', articleTitle);
            gr.setValue('rating', rating);
            gr.setValue('comment', comment);
            gr.setValue('score', score);
            var sysId = gr.insert();

            return JSON.stringify({ success: true, sys_id: sysId + '' });
        } catch (e) {
            return JSON.stringify({ success: false, error: e.toString() });
        }
    },
    type: 'AICopilotFeedback',
})
